package kr.signal.mealcaremacro;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
public class MainActivity extends Activity {
 LocalDate date=LocalDate.now(); TextView dateView,status,log; CheckBox preview; RadioGroup meals,menus; TextView selectedInfo; final Handler h=new Handler(); 
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff20252a);t.setPadding(0,dp(6),0,dp(6));return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setOnClickListener(v->r.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{date=LocalDate.parse(getPreferences(0).getString("date",date.toString()));}catch(Exception ignored){}
 ScrollView sc=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(24),dp(26),dp(24),dp(24));sc.addView(l);setContentView(sc);
 l.addView(text("밀케어 자동 예약",28));l.addView(text("v1.2.0 · 평일 날짜별 1개",13));
 l.addView(text("식사 · 수령 장소 선택",19));meals=new RadioGroup(this);meals.setOrientation(RadioGroup.VERTICAL);addOption(meals,"중식 (R&D센터)",101);addOption(meals,"중식 (통합생산동)",103);addOption(meals,"석식 (사내식당)",102);l.addView(meals);int mealId=getPreferences(0).getInt("mealId",getPreferences(0).getBoolean("lunch",false)?101:102);meals.check(mealId==101||mealId==103?mealId:102);
 l.addView(text("메뉴 선택",19));menus=new RadioGroup(this);menus.setOrientation(RadioGroup.VERTICAL);for(int i=0;i<MealSelection.MENUS.length;i++)addOption(menus,MealSelection.MENUS[i],201+i);l.addView(menus);int menuIndex=getPreferences(0).getInt("menuIndex",3);menus.check(201+Math.max(0,Math.min(3,menuIndex)));
 selectedInfo=text("",14);l.addView(selectedInfo);meals.setOnCheckedChangeListener((group,id)->saveSelection());menus.setOnCheckedChangeListener((group,id)->saveSelection());saveSelection();
 l.addView(text("예약 시작 날짜 (포함)",19));
 dateView=text(date.toString(),22);l.addView(dateView);l.addView(button("날짜 선택",()->new DatePickerDialog(this,(v,y,m,d)->{date=LocalDate.of(y,m+1,d);dateView.setText(date.toString());getPreferences(0).edit().putString("date",date.toString()).apply();},date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show()));
 preview=new CheckBox(this);preview.setText("예약하지 않고 탐색만 하기");l.addView(preview);
 l.addView(button("접근성 권한 설정",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))));
 l.addView(button("시작",()->startMacro()));l.addView(button("중지",()->{if(MacroService.instance!=null)MacroService.instance.stop("사용자 중지");}));
 status=text("",15);l.addView(status);l.addView(text("실행 기록",19));log=text("",13);l.addView(log);
 l.addView(button("상세 로그 TXT 저장",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"mealcare-diagnostic-"+LocalDate.now()+".txt");startActivityForResult(i,701);}));l.addView(text("상세 로그에는 밀케어 화면에서 읽은 텍스트와 좌표가 포함됩니다. 공유 전에 개인정보를 확인하세요.",12));l.addView(button("기록 공유",()->{Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,getSharedPreferences("run",0).getString("log",""));startActivity(Intent.createChooser(i,"실행 기록"));}));
 l.addView(button("선택한 식사·메뉴 예약 기록 초기화",()->{MealSelection selected=selection();new AlertDialog.Builder(this).setMessage(selected.display+"의 앱 내부 중복 방지 기록만 지웁니다. 실제 예약은 취소되지 않습니다.").setNegativeButton("취소",null).setPositiveButton("초기화",(d,w)->{if(MacroService.instance==null||!MacroService.instance.running)getSharedPreferences("run",0).edit().remove(selected.key).apply();}).show();}));
 }
 void addOption(RadioGroup group,String label,int id){RadioButton rb=new RadioButton(this);rb.setId(id);rb.setText(label);rb.setTextSize(15);rb.setPadding(dp(4),dp(5),dp(8),dp(5));group.addView(rb);}
 MealSelection selection(){int index=Math.max(0,Math.min(3,menus.getCheckedRadioButtonId()-201));int id=meals.getCheckedRadioButtonId();return new MealSelection(id==101?MealSelection.RD:id==103?MealSelection.PRODUCTION:MealSelection.DINNER,MealSelection.MENUS[index]);}
 void saveSelection(){MealSelection s=selection();getPreferences(0).edit().putBoolean("lunch",s.lunch).putInt("mealId",meals.getCheckedRadioButtonId()).putInt("menuIndex",menus.getCheckedRadioButtonId()-201).apply();selectedInfo.setText(s.display+" · 날짜별 1개 · 토/일 제외");}
 void startMacro(){if(MacroService.instance==null){status.setText("접근성 설정에서 밀케어 예약 자동화를 켜주세요.");return;} if(MacroService.instance.running)return;
 Intent query=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);ArrayList<ResolveInfo> matches=new ArrayList<>();
 for(ResolveInfo ri:getPackageManager().queryIntentActivities(query,0)){String label=ri.loadLabel(getPackageManager()).toString().replaceAll("\\s+","").toLowerCase(Locale.ROOT);if((label.equals("mealcare")||label.equals("밀케어")||label.equals("밀케어앱"))&&!ri.activityInfo.packageName.equals(getPackageName()))matches.add(ri);}
 if(matches.size()!=1){status.setText("밀케어 앱을 정확히 찾지 못했습니다. 앱 설치와 이름을 확인하세요.");return;}
 ResolveInfo ri=matches.get(0);Intent launch=getPackageManager().getLaunchIntentForPackage(ri.activityInfo.packageName);if(launch==null){status.setText("밀케어 실행 불가");return;}
 final MealSelection selected=selection();final LocalDate chosenDate=date;final boolean dry=preview.isChecked();new AlertDialog.Builder(this).setTitle(dry?"탐색 시작":"예약 시작").setMessage(selected.display+"\n"+chosenDate+"부터 평일마다 예약 가능한 상품을 1개씩 "+(dry?"탐색합니다.":"예약합니다.")).setNegativeButton("취소",null).setPositiveButton("시작",(d,w)->{if(MacroService.instance!=null){MacroService.instance.begin(ri.activityInfo.packageName,chosenDate,dry,selected);startActivity(launch);}}).show();
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=701||result!=RESULT_OK||data==null||data.getData()==null)return;try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("open failed");for(String name:new String[]{"mealcare-diagnostic-prev.txt","mealcare-diagnostic.txt"}){File f=new File(getFilesDir(),name);if(f.exists())try(FileInputStream in=new FileInputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}}Toast.makeText(this,"상세 로그 저장 완료",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"저장 실패: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 final Runnable refresh=new Runnable(){public void run(){SharedPreferences p=getSharedPreferences("run",0);status.setText((MacroService.instance==null?"접근성 꺼짐":"접근성 연결됨")+" · "+p.getString("status","대기"));log.setText(p.getString("log",""));h.postDelayed(this,800);}};
 @Override protected void onResume(){super.onResume();h.removeCallbacks(refresh);h.post(refresh);}
 @Override protected void onPause(){h.removeCallbacks(refresh);super.onPause();}
}